// Express-style routing: first registered match wins
const routes = [];
function get(pattern, name) { routes.push({ pattern, name }); }

// Match "/api/books/:id" style patterns segment by segment
function match(pattern, path) {
  const p = pattern.split('/'), q = path.split('/');
  if (p.length !== q.length) return null;
  const params = {};
  for (let i = 0; i < p.length; i++) {
    if (p[i].startsWith(':')) params[p[i].slice(1)] = q[i]; // :id matches ANY segment
    else if (p[i] !== q[i]) return null;
  }
  return params;
}

function dispatch(path) {
  for (const r of routes) {            // registration order, stop at first hit
    const params = match(r.pattern, path);
    if (params) return r.name + ' ' + JSON.stringify(params);
  }
  return '404';
}

