# Service depends on a repository interface, so a fake makes unit tests instant
class FakeRepo:
    def __init__(self):
        self.rows, self.saves = [], 0
    def find_by_isbn(self, isbn):
        return next((r for r in self.rows if r["isbn"] == isbn), None)
    def save(self, book):
        self.saves += 1
        self.rows.append(book)
        return len(self.rows)

class BookService:
    def __init__(self, repo):
        self.repo = repo  # injected: could be SQL later, no change here
    def create(self, book):
        errors = []
        if not book.get("title"): errors.append("title required")
        if not book.get("isbn"): errors.append("isbn required")
        if errors: raise ValueError(errors)           # all errors, not just first
        if self.repo.find_by_isbn(book["isbn"]): raise KeyError("duplicate isbn")
        return self.repo.save(book)

repo = FakeRepo(); svc = BookService(repo)
print("valid    ->", svc.create({"title": "Dune", "isbn": "1"}))
for bad in ({"title": "", "isbn": ""}, {"title": "Dune", "isbn": "1"}):
    try: svc.create(bad)
    except Exception as e: print("rejected ->", type(e).__name__, e.args[0])
print("save calls:", repo.saves, "(expected 1)")

# Optimistic concurrency: update only if the version still matches
class Store:
    def __init__(self):
        self.rows = {1: {"title": "Dune", "version": 1}}

    def get(self, id):
        r = self.rows[id]
        return dict(r)  # the client keeps a copy and its version (the ETag)

    def update(self, id, title, if_match):
        r = self.rows[id]
        # compare and write happen together (one atomic step in a real DB)
        if r["version"] != if_match:
            return 412, "Precondition Failed"
        r["title"] = title
        r["version"] += 1
        return 200, dict(r)

s = Store()
alice = s.get(1)
bob = s.get(1)
print("both read:", alice)
print("alice saves:", s.update(1, "Dune (2nd ed)", alice["version"]))
print("bob saves  :", s.update(1, "Dune Messiah", bob["version"]))
# Bob must refetch, merge, and retry with the new version
bob = s.get(1)
print("bob retries:", s.update(1, "Dune Messiah", bob["version"]))

