import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

public class Main {
    static long unsafeNext = 0;                      // plain field
    static final AtomicLong safeNext = new AtomicLong();

    public static void main(String[] args) throws Exception {
        Set<Long> unsafeIds = ConcurrentHashMap.newKeySet();
        Set<Long> safeIds = ConcurrentHashMap.newKeySet();
        ExecutorService pool = Executors.newFixedThreadPool(4);
        List<Future<?>> fs = new ArrayList<>();
        for (int t = 0; t < 4; t++) {
            fs.add(pool.submit(() -> {
                for (int i = 0; i < 1000; i++) {
                    unsafeIds.add(unsafeNext++);              // read-modify-write: not atomic
                    safeIds.add(safeNext.getAndIncrement());   // one atomic step
                }
            }));
        }
        for (Future<?> f : fs) f.get();
        pool.shutdown();
        System.out.println("requests: 4 threads x 1000 = 4000");
        System.out.println("atomic ids distinct: " + safeIds.size());
        // unsafe count varies per run, but can never exceed 4000 (duplicates appear)
        System.out.println("unsafe ids <= 4000: " + (unsafeIds.size() <= 4000));
    }
}
